-- Editable transactional email templates (React Email / @betterflag/emails).
-- The lifecycle worker reads compiled_html + subject + text and substitutes
-- {{variables}} per recipient. The admin editor edits the source fields and
-- re-renders compiled_html via @betterflag/emails on save.

create table if not exists public.email_templates (
  key         text primary key,
  name        text not null,
  description text not null default '',
  subject     text not null,
  preview     text not null default '',
  eyebrow     text not null default '',
  heading     text not null default '',
  body_html   text not null,
  text        text not null,
  compiled_html text not null,
  variables   jsonb not null default '[]'::jsonb,
  version     integer not null default 1,
  updated_by  text,
  updated_at  timestamptz not null default now(),
  created_at  timestamptz not null default now()
);

-- Admin-only data: service role (workers + admin server actions) bypasses RLS;
-- no anon/authenticated policies means the dashboard's user tokens can't read it.
alter table public.email_templates enable row level security;

insert into public.email_templates
  (key, name, description, subject, preview, eyebrow, heading, body_html, text, compiled_html, variables)
values
  ('welcome', 'Welcome', 'Day 0 — sent right after an org is created.', 'Welcome to BetterFlag: your first flag is 5 minutes away', 'Create a flag, curl the edge, watch it flip. About 5 minutes.', 'Welcome', 'Your first flag is 5 minutes away', '<p style="margin:0 0 16px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;font-size:15px;line-height:1.65;color:#171717;">Hey, Mehdi here. I built BetterFlag.</p>
